// Channel import: translate a request written for another channel (fal, ...) into a Yir Standard
// request, with a per-field difference report. Zero dependencies and pure: the dialect table
// (fal-dialect.json) is generated by generate-fal-dialect.mjs in the Yir repository; no network.
// Rules: the model maker's semantics are the pivot; the source channel's defaults are written out
// explicitly instead of relying on Yir's defaults; anything without an exact equivalent is rejected
// with a reason, never approximated. Source of truth: Yir repository scripts/channel-import/.

// Pixel sizes of fal's image_size presets (fixed enum in fal's docs).
const FAL_IMAGE_SIZE_PRESETS = {
  square_hd: [1024, 1024],
  square: [512, 512],
  portrait_4_3: [768, 1024],
  portrait_16_9: [576, 1024],
  landscape_4_3: [1024, 768],
  landscape_16_9: [1024, 576],
}

// normalizeValue writes a channel value the Yir way: "5s" becomes 5, strings take the contract's spelling.
export function normalizeValue(param, value, spec) {
  if (param === 'duration' && typeof value === 'string') {
    const seconds = value.trim().toLowerCase().match(/^(\d+)s?$/)
    if (seconds) return Number(seconds[1])
    if (value.trim().toLowerCase() === 'auto') return 'auto'
  }
  if (param === 'aspect_ratio' && typeof value === 'string' && ['auto', 'adaptive'].includes(value.trim().toLowerCase()) && spec) {
    // The maker's adaptive and a channel's auto mean the same; use this model's contract spelling.
    const adaptive = spec.values?.find(v => v === 'auto' || v === 'adaptive')
    if (adaptive) return adaptive
  }
  if (typeof value === 'string' && spec) {
    const spelled = [...(spec.values ?? []), ...(spec.string_values ?? [])].find(
      v => typeof v === 'string' && v.toLowerCase() === value.trim().toLowerCase(),
    )
    if (spelled !== undefined) return spelled
  }
  return value
}

// allowed checks a value against the Yir contract snapshot. The snapshot only explains problems early;
// a Yir Quote is the final authority.
export function allowed(spec, value) {
  if (!spec) return false
  if (spec.values?.some(v => v === value)) return true
  if (spec.string_values?.includes(value)) return true
  if (!spec.values && Number.isInteger(value) && spec.minimum !== undefined && spec.maximum !== undefined) {
    return value >= spec.minimum && value <= spec.maximum
  }
  return false
}

function describeAllowed(spec) {
  if (!spec) return '(not a parameter in this mode)'
  if (spec.values) return [...spec.values, ...(spec.string_values ?? [])].join(', ')
  if (spec.minimum !== undefined) return `${spec.minimum}–${spec.maximum}${spec.string_values ? ', ' + spec.string_values.join(', ') : ''}`
  return 'see the model contract'
}

const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null)

// A K tier is known only when the long edge equals the tier's base edge; other sizes have no equivalent.
const TIER_BY_LONG_EDGE = { 512: '0.5K', 1024: '1K', 2048: '2K', 4096: '4K' }

// imageSizeToParameters maps fal image_size (preset, "WxH", "auto", "auto_2K" or {width,height}) to Yir
// parameters, or returns null. Yir delivers a tier plus aspect ratio; exact pixels depend on the channel.
function imageSizeToParameters(value, yirParameters) {
  if (typeof value === 'string') {
    const auto = value.trim().toLowerCase().match(/^auto(?:_(\d+k))?$/)
    if (auto) {
      const aspect = normalizeValue('aspect_ratio', 'auto', yirParameters.aspect_ratio)
      if (!allowed(yirParameters.aspect_ratio, aspect)) return null
      const result = { aspect_ratio: aspect }
      if (auto[1]) {
        const tier = normalizeValue('resolution', auto[1], yirParameters.resolution)
        if (!allowed(yirParameters.resolution, tier)) return null
        result.resolution = tier
      }
      return result
    }
  }
  let pixels = typeof value === 'string' ? FAL_IMAGE_SIZE_PRESETS[value] : value && [value.width, value.height]
  if (!pixels && typeof value === 'string') {
    const wh = value.trim().match(/^(\d+)\s*[x*]\s*(\d+)$/i)
    if (wh) pixels = [Number(wh[1]), Number(wh[2])]
  }
  if (!pixels || !Number.isInteger(pixels[0]) || !Number.isInteger(pixels[1])) return null
  const [width, height] = pixels
  const exact = `${width}x${height}`
  if (allowed(yirParameters.size, exact)) return { size: exact }
  const gcd = (a, b) => (b ? gcd(b, a % b) : a)
  const g = gcd(width, height)
  const ratio = `${width / g}:${height / g}`
  if (!allowed(yirParameters.aspect_ratio, ratio)) return null
  const result = { aspect_ratio: ratio }
  if (yirParameters.resolution) {
    const tier = TIER_BY_LONG_EDGE[Math.max(width, height)]
    const spelled = tier && normalizeValue('resolution', tier, yirParameters.resolution)
    if (!spelled || !allowed(yirParameters.resolution, spelled)) return null
    result.resolution = spelled
  }
  return result
}

/**
 * translate turns one channel request into a Yir Standard request.
 * @param {object} dialect  dialect table (fal-dialect.json)
 * @param {string} endpoint channel endpoint ID, e.g. "bytedance/seedance-2.5/image-to-video"
 * @param {object} input    channel request body
 * @returns {{ok: boolean, request?: object, jobs: number, report: Array<{field: string, action: string, detail: string}>, errors: Array<{field: string, reason: string}>}}
 */
export function translate(dialect, endpoint, input) {
  const report = []
  const errors = []
  const entry = dialect.endpoints[endpoint]
  if (!entry) {
    return { ok: false, jobs: 0, report, errors: [{ field: '(endpoint)', reason: `no ${dialect.channel} endpoint ${endpoint} in the dialect table; Yir may not offer this model, or it is not mapped yet` }] }
  }
  if (entry.unsupported) {
    return { ok: false, jobs: 0, report, errors: [{ field: '(endpoint)', reason: entry.unsupported }] }
  }
  const body = input ?? {}
  const parameters = {}
  const references = []
  let prompt
  let jobs = 1

  for (const name of Object.keys(body)) {
    if (!entry.fields[name]) errors.push({ field: name, reason: `not a field of this ${dialect.channel} endpoint` })
  }

  for (const [name, field] of Object.entries(entry.fields)) {
    const present = Object.hasOwn(body, name) && body[name] !== null && body[name] !== undefined
    const value = body[name]
    switch (field.kind) {
      case 'prompt':
        if (present) prompt = String(value)
        break
      case 'reference': {
        if (!present) {
          if (field.required) errors.push({ field: name, reason: 'required input file is missing' })
          break
        }
        const urls = Array.isArray(value) ? value : [value]
        for (const url of urls) references.push({ role: field.role, url })
        report.push({ field: name, action: 'mapped', detail: `input.references[].role=${field.role} (${urls.length})` })
        break
      }
      case 'param': {
        const spec = entry.yir_parameters[field.param]
        const raw = present ? value : field.fal_default
        if (raw === undefined || raw === null) break
        const normalized = normalizeValue(field.param, raw, spec)
        if (!allowed(spec, normalized)) {
          const source = present ? 'value' : `${dialect.channel} default`
          errors.push({ field: name, reason: `${source} ${JSON.stringify(raw)} is not an allowed ${field.param} for Yir ${entry.model} (allowed: ${describeAllowed(spec)})${present ? '' : '; pass one of the allowed values explicitly'}` })
          break
        }
        parameters[field.param] = normalized
        report.push(present
          ? { field: name, action: 'mapped', detail: `parameters.${field.param}=${JSON.stringify(normalized)}` }
          : { field: name, action: 'filled_default', detail: `not set; wrote the ${dialect.channel} default explicitly: parameters.${field.param}=${JSON.stringify(normalized)}` })
        break
      }
      case 'output_count': {
        const count = present ? Number(value) : 1
        if (!Number.isInteger(count) || count < 1) {
          errors.push({ field: name, reason: `invalid value ${JSON.stringify(value)}` })
        } else if (count > 1) {
          jobs = count
          report.push({ field: name, action: 'split', detail: `a Yir Job returns one output: submit ${count} Jobs, each with its own idempotency key; billed per output as on ${dialect.channel}` })
        }
        break
      }
      case 'image_size': {
        const raw = present ? value : field.fal_default
        if (raw === undefined || raw === null) break
        const mapped = imageSizeToParameters(raw, entry.yir_parameters)
        if (!mapped) {
          errors.push({ field: name, reason: `${present ? 'value' : `${dialect.channel} default`} ${JSON.stringify(raw)} has no exact Yir resolution tier and aspect ratio; set resolution / aspect_ratio from the Yir model contract instead` })
          break
        }
        Object.assign(parameters, mapped)
        report.push({ field: name, action: present ? 'mapped' : 'filled_default', detail: `${JSON.stringify(raw)} → ${Object.entries(mapped).map(([k, v]) => `parameters.${k}=${JSON.stringify(v)}`).join(', ')}` })
        break
      }
      case 'delivery':
        if (present && !same(value, field.fal_default)) {
          errors.push({ field: name, reason: `${field.note}; non-default value ${JSON.stringify(value)} is not supported` })
        } else if (present) {
          report.push({ field: name, action: 'ignored_default', detail: field.note })
        }
        break
      case 'metadata':
        if (present) report.push({ field: name, action: 'ignored', detail: 'metadata only, does not affect the output' })
        break
      case 'default_only':
        if (present && !same(value, field.fal_default)) {
          errors.push({ field: name, reason: `${dialect.channel}-specific option; Yir only accepts its default ${JSON.stringify(field.fal_default ?? null)} because other channels cannot honour it` })
        } else if (present) {
          report.push({ field: name, action: 'ignored_default', detail: 'same as the default; dropped' })
        }
        break
      case 'unsupported':
        if (present) errors.push({ field: name, reason: field.note })
        break
      default:
        errors.push({ field: name, reason: `unknown field kind ${field.kind}` })
    }
  }

  // Yir parameters the channel has no field for run with Yir's default; list them for review.
  for (const [param, spec] of Object.entries(entry.yir_parameters)) {
    if (param in parameters || spec.default === undefined || param === 'n') continue
    report.push({ field: `(yir) ${param}`, action: 'yir_default', detail: `no ${dialect.channel} field; Yir uses its default ${JSON.stringify(spec.default)}` })
  }

  // Check input file counts (total and per role) before submitting, so Yir does not reject later.
  const limits = entry.references ?? { min: 0, max: 0 }
  if (references.length < limits.min || references.length > limits.max) {
    errors.push({ field: '(references)', reason: `Yir ${entry.model} ${entry.input_type} mode takes ${limits.min}–${limits.max} input files; the request has ${references.length}` })
  }
  for (const [role, range] of Object.entries(limits.by_role ?? {})) {
    const count = references.filter(r => r.role === role).length
    if (count < (range.minimum ?? 0) || (range.maximum !== undefined && count > range.maximum)) {
      errors.push({ field: '(references)', reason: `Yir ${entry.model} needs ${range.minimum ?? 0}–${range.maximum ?? 'any'} ${role} files; the request has ${count}` })
    }
  }

  const request = { model: entry.model, input: { type: entry.input_type }, parameters }
  if (prompt !== undefined) request.input.prompt = prompt
  if (references.length) request.input.references = references
  return { ok: errors.length === 0, request: errors.length ? undefined : request, jobs, report, errors }
}
